import graph3;
size(6.5cm);
currentprojection=orthographic(6,-9,5);
surface s=surface(new triple(pair q) {
  return (cos(q.x),sin(q.x),q.y);
},(0,0),(2pi,2),36,12);
draw(s,rgb(0.39,0.69,0.84)+opacity(0.42));
path3 base=(1,0,0), top=(1,0,2);
for(int k=1; k<72; ++k) {
  real t=2pi*k/72;
  base=base--(cos(t),sin(t),0);
  top=top--(cos(t),sin(t),2);
}
draw(base--cycle,rgb(0.12,0.37,0.70)+linewidth(1.0pt));
draw(top--cycle,rgb(0.12,0.37,0.70)+linewidth(1.0pt));
draw(O--(1.7,0,0),gray(0.48),Arrow3);
draw(O--(0,1.7,0),gray(0.48),Arrow3);
draw(O--(0,0,2.5),gray(0.48),Arrow3);
label("$x$",(1.7,0,0),2E);
label("$y$",(0,1.7,0),2N);
label("$z$",(0,0,2.5),2N);
label("$x^2+y^2=1$",(0,0,2.5),2N);

import graph3;
size(6.5cm);
currentprojection=orthographic(6,-9,5);
surface s=surface(new triple(pair q) {
  return (q.x,q.x*q.x,q.y);
},(-1.35,0),(1.35,2),28,12);
draw(s,rgb(0.63,0.51,0.84)+opacity(0.48));
path3 base=(-1.35,1.35*1.35,0), top=(-1.35,1.35*1.35,2);
for(int k=1; k<=60; ++k) {
  real x=-1.35+2.7*k/60;
  base=base--(x,x*x,0);
  top=top--(x,x*x,2);
}
draw(base,rgb(0.44,0.23,0.66)+linewidth(1.0pt));
draw(top,rgb(0.44,0.23,0.66)+linewidth(1.0pt));
draw(O--(1.8,0,0),gray(0.48),Arrow3);
draw(O--(0,2.5,0),gray(0.48),Arrow3);
draw(O--(0,0,2.5),gray(0.48),Arrow3);
label("$x$",(1.8,0,0),2E);
label("$y$",(0,2.5,0),2N);
label("$z$",(0,0,2.5),2N);
label("$y=x^2$",(0,1.2,2.4),2N);

