import graph3;
size(10cm);
currentprojection=orthographic(7,-10,7);
surface saddle=surface(new triple(pair q) {
  return (q.x,q.y,q.x*q.x-q.y*q.y);
},(-1.4,-1.4),(1.4,1.4),28,28);
draw(saddle,rgb(0.64,0.73,0.88)+opacity(0.38));
for(int j=-1; j<=1; ++j) {
  real c=0.8*j;
  path3 alongX=(-1.4,c,1.4*1.4-c*c);
  path3 alongY=(c,-1.4,c*c-1.4*1.4);
  for(int k=1; k<=80; ++k) {
    real v=-1.4+2.8*k/80;
    alongX=alongX--(v,c,v*v-c*c);
    alongY=alongY--(c,v,c*c-v*v);
  }
  draw(alongX,rgb(0.14,0.38,0.73)+linewidth(1.0pt));
  draw(alongY,rgb(0.78,0.22,0.14)+linewidth(1.0pt));
}
draw(O--(2,0,0),gray(0.45),Arrow3);
draw(O--(0,2,0),gray(0.45),Arrow3);
draw((0,0,-2.2)--(0,0,2.2),gray(0.45),Arrow3);
label("$x$",(2,0,0),2E);
label("$y$",(0,2,0),2N);
label("$z$",(0,0,2.2),2N);
label("$y=c$",(1.3,-0.8,1.3*1.3-0.8*0.8),2E,rgb(0.14,0.38,0.73));
label("$x=c$",(-0.8,1.3,0.8*0.8-1.3*1.3),2N,rgb(0.78,0.22,0.14));

hint.p:
Think about how each trace changes as you move the cutting plane. It is not one slice
that identifies the surface. Here the formula describes every horizontal slice;
a finite selection alone could miss changes between the selected planes.
